var database;
exports.readDB = function( callback )
{
    console.log( "enter helper readDB");
    if( database )
    {
        console.log( "BD had been loaded.");
        callback();

        //this should be only called after 'database' is initialized.
        //This function will pre-load the photo file names so it won't have a async called later
        //when creating photo pages.
        cachePhotoNames();
    }
    else
    {
        console.log( "load DB now.");
        fs.readFile("./test.db", function(err, data) {
            if (err) {
                console.log("DB Not Found.");
            }
            else {
                database = new sql.Database(data);
                console.log("DB is loaded.");
                callback();

                //The following methods should be only called after 'database' is initialized.

                //This function will pre-load the photo file names so it won't have a async called later
                //when creating photo pages.
                cachePhotoNames();

                //storyPageHelper.buildStoryPage();
                temperatureHelper.buildTemperatureData();//  buildLessonPage();
            }
        });
    }
}

const MAX_ARTICLE_IN_HOMEPAGE = 35;
exports.getAllArticles = function() {
    console.log( "enter getAllArticles");
    //var result = database.exec("SELECT * FROM articles WHERE category != 0x1 ORDER BY id DESC LIMIT " + MAX_ARTICLE_IN_HOMEPAGE );
    var result = database.exec("SELECT * FROM articles WHERE category != 0x1 ORDER BY year DESC, month DESC, day DESC LIMIT " + MAX_ARTICLE_IN_HOMEPAGE );

    //only one 'select', so just need to return [0] which is the first 'select' result
    return result[0].values;
}

exports.getLessons = function(){
    console.log("helper :: getStories() " );

    const sqlString = "SELECT * FROM stories";

    const result = database.exec(sqlString);

    if( null == result[0]){
        console.log( "empty story data")
        return null;
    }

    return result[0].values;
}


exports.getStories = function(){
    console.log("helper :: getStories() " );

    const sqlString = "SELECT * FROM stories ORDER BY year DESC, month DESC, day DESC";

    const result = database.exec(sqlString);

    if( null == result[0]){
        console.log( "empty story data")
        return null;
    }

    return result[0].values;
}

exports.getArticles = function( type ){
    console.log("helper :: getArticles : " + type );
    //var sqlString = "SELECT * FROM articles WHERE category & " + type + " != 0 ORDER BY id DESC ";

    //var sqlString = "SELECT * FROM articles WHERE category & " + type + " != 0 AND year = 2017 ORDER BY month  DESC";
    var sqlString = "SELECT * FROM articles WHERE category & " + type + " != 0 ORDER BY year DESC, month DESC, day DESC";
    //SELECT * FROM articles WHERE year = 2016 GROUP BY month ORDER BY month ASC

    console.log("sql string: "+ sqlString);
    var result = database.exec(sqlString);

    //bug: the result[] may be empty at some moment, e.g. 1st in new year.
    if( null == result[0]){
        console.log( "empty data")
        return null;
    }

    return result[0].values;
}

exports.getArticle = function( ID ){
    console.log( "enter getArticle(ID)");
    var result = database.exec("SELECT * FROM articles WHERE id = " + ID );

    //only one 'select', so just need to return [0] which is the first 'select' result
    return result[0].values;
}

var photoNames = [];

exports.getPhotoNames = function( key ){
    console.log("getPhotoNames for key : " + key );
    return photoNames[key];
}

function cachePhotoNames(){
    console.log("enter cachePhotoNames");
    var articleData = module.exports.getArticles( module.exports.PHOTO_TYPE() );
    photoNames = []; //reset first
    var photoRootPath = "./photos"
    fs.readdir(photoRootPath, function(err, items) {

        if (err != null) {
            console.log("cachePhotoNames error: " + err);
            return false; //indicate error to caller
        }
        else {
            console.log("cachePhotoNames result: " + items);

            var photoFolderCount = items.length;
            for(var i = 0; i< photoFolderCount; ++i){
                console.log("photo folder " + i + " : " + items[i]);

                readPhotoDir( photoRootPath + "/" + items[i]);
            }
        }
    });
    return true;
}

function readPhotoDir( photoPath){
    console.log("enter readPhotoDir :" + photoPath);
    fs.readdir(photoPath, function(err, items) {

        if (err != null) {
            console.log("readPhotoDir error: " + err);
            return "";
        }
        else {
            console.log("readPhotoDir result: " + items);

            var newPhotoNames = [];
            var photoCount = items.length;
            for(var i = 0; i< photoCount; ++i){

                //remove thumb photo which will be added later in client side
                if( -1 == items[i].indexOf("-s") ){
                    newPhotoNames.push(items[i]);
                }
            }
            photoNames[photoPath] = newPhotoNames ;//.toString();



        }
    });
}